<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/includes/medical_activity.php';
require_once __DIR__.'/includes/ui_shell.php';
header('Cache-Control: no-store, private');
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);header('Allow: GET');exit;}
try{$view=medicalActivityRead($pdo,$_GET);}catch(PDOException){http_response_code(503);exit('Podklady nyní nelze načíst. Nejde o potvrzení jejich platnosti.');}catch(InvalidArgumentException $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}catch(DomainException|RuntimeException $e){http_response_code(403);exit('Přehled není ve vašem aktuálním pracovním rozsahu.');}
$teams=$pdo->query('SELECT t.id,t.name FROM club_teams t WHERE '.coachScopeTargetPredicate($pdo,'team','t.id').' ORDER BY t.name,t.id')->fetchAll(PDO::FETCH_ASSOC);
function maH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Podklady před aktivitou</title><?php appUiAssets();?></head><body><?php require __DIR__.'/hlavicka.php';?><main class="container py-4">
<h1>Podklady před aktivitou</h1><p>Platnost k vybranému dni, bez soukromých dokumentů. O účasti rozhoduje pověřený pracovník podle pravidel konkrétní činnosti.</p>
<?php if($view['planId']):?><h2 class="h4"><?=maH($view['context'])?> · <?=maH($view['on'])?></h2><p><a href="training_closure_admin.php?plan_id=<?=$view['planId']?>">Zpět k lekci</a> · <a href="medical_activity_admin.php">Vybrat skupinu a datum</a></p><p>Pravidelná soupiska k datu lekce, rezervovaní náhradníci a zapsaní účastníci. Tento seznam nepotvrzuje skutečnou docházku.</p><?php endif;?>
<form method="get" class="row g-2 mb-3"><?php if($view['planId']):?><input type="hidden" name="plan_id" value="<?=$view['planId']?>"><?php else:?><label class="col-md-5">Skupina / soupiska<select class="form-select" name="team_id" required><option value="">Vyberte</option><?php foreach($teams as $t):?><option value="<?=(int)$t['id']?>" <?=$view['teamId']===(int)$t['id']?'selected':''?>><?=maH($t['name'])?></option><?php endforeach;?></select></label><label class="col-md-3">Den aktivity<input class="form-control" type="date" name="on" value="<?=maH($view['on'])?>" required></label><?php endif;?>
<label class="col-md-4">Osoba<input class="form-control" name="q" maxlength="100" value="<?=maH($view['search'])?>"></label><label class="col-md-4">Stav<select class="form-select" name="state"><option value="">Všechny</option><?php foreach(medicalActivityLabels() as $key=>$label):?><option value="<?=$key?>" <?=$view['state']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><div class="col-12"><button class="btn btn-primary">Zobrazit</button></div></form>
<?php if(!$view['planId']&&!$view['teamId']):?><p>Vyberte skupinu a datum nebo otevřete přehled z konkrétní lekce.</p><?php else:?>
<p role="status">Nalezeno: <?=$view['total']?> · strana <?=$view['page']?> z <?=$view['pages']?></p>
<div class="table-responsive"><table class="table"><tr><th>Osoba / účel</th><th>Stav k <?=maH($view['on'])?></th><th>Další krok</th></tr><?php foreach($view['rows'] as $row):?><tr><td><?=maH($row['name'])?><br><small><?=maH($row['purpose'])?></small></td><td><?=maH(medicalActivityLabels()[$row['attention_status']])?><?= $row['valid_until']?' do '.maH($row['valid_until']):''?></td><td><?=maH($row['next_step'])?><br><?php if(staffActivePositionIs('registrar')):?><a href="medical_clearance_admin.php?person_id=<?=$row['person_id']?>">Vyřídit podklady osoby</a><?php else:?><a href="medical_clearance_status.php?person_id=<?=$row['person_id']?>&amp;on=<?=maH($view['on'])?>">Stav osoby k datu</a><?php endif;?></td></tr><?php endforeach;?></table></div>
<?php if(!$view['rows']):?><p>Pro tento výběr není žádný výsledek. Nulový výsledek nepotvrzuje splnění požadavků jiných skupin nebo účelů.</p><?php endif;?>
<?php foreach(['Předchozí'=>-1,'Další'=>1] as $label=>$delta):$p=$view['page']+$delta;if($p<1||$p>$view['pages'])continue;?><a class="btn btn-outline-secondary me-2" href="?<?=maH(http_build_query(['plan_id'=>$view['planId'],'team_id'=>$view['teamId'],'on'=>$view['on'],'q'=>$view['search'],'state'=>$view['state'],'page'=>$p]))?>"><?=$label?></a><?php endforeach;?>
<?php endif;?></main></body></html>
